"use client";

import { type HTMLAttributes, useRef } from "react";
import { createScrollbars } from "../interaction/scrollbar";
import { cx } from "../utils/cx";
import { useEffect } from "react";

export type ScrollAreaProps = HTMLAttributes<HTMLDivElement> & {
  /** Which scrollbars to offer. Default `vertical`. */
  orientation?: "vertical" | "horizontal" | "both";
  /** Fade the content toward an edge that has more to scroll. Default true. */
  fade?: boolean;
  /** Names the scrollable region (recommended: a scroll container is focusable). */
  "aria-label"?: string;
};

/**
 * A scroll container with slim overlay scrollbars that appear while you scroll or hover, and edge fades that show
 * where there is more. Native scrolling is untouched (wheel, touch, keyboard, find in page); the thumbs are drawn
 * from the scroll metrics and can be dragged. Give it a height (or `max-height`) in CSS.
 */
export function ScrollArea({ orientation = "vertical", fade = true, className, children, ...rest }: ScrollAreaProps) {
  const root = useRef<HTMLDivElement>(null);
  const viewport = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!root.current || !viewport.current) return;
    return createScrollbars(root.current, viewport.current);
  }, []);
  return (
    <div
      ref={root}
      className={cx("hm-scrollarea", className)}
      data-orientation={orientation}
      data-fade={fade ? "" : undefined}
    >
      <div {...rest} ref={viewport} className="hm-scroll-viewport" tabIndex={0} role="region">
        <div className="hm-scroll-content">{children}</div>
      </div>
      {orientation !== "horizontal" ? (
        <div className="hm-scrollbar" data-scroll-bar="y" aria-hidden="true">
          <div className="hm-scroll-thumb" data-scroll-thumb="" />
        </div>
      ) : null}
      {orientation !== "vertical" ? (
        <div className="hm-scrollbar" data-scroll-bar="x" aria-hidden="true">
          <div className="hm-scroll-thumb" data-scroll-thumb="" />
        </div>
      ) : null}
    </div>
  );
}
